#!/bin/bash
# SLURM array job: one shard of the data set per array task, generated by run_shard.sh.
#
# ADAPT TO YOUR CLUSTER before use: the partition and account, the limits, how Python is provided (modules), and the
# settings of run_shard.sh (events per shard, output directory). Submit from the repository root:
#
#     mkdir -p logs
#     sbatch examples/cluster/slurm_array.sh
#     squeue --me                                   # follow the jobs
#
#SBATCH --job-name=flashsim
#SBATCH --array=0-9                  # 10 shards, indices 0 to 9 (add %4 to run at most 4 at a time: 0-9%4)
#SBATCH --cpus-per-task=4
#SBATCH --mem=2G
#SBATCH --time=00:30:00
#SBATCH --output=logs/%x_%A_%a.out   # job name, array job id, array index
##SBATCH --partition=cpu             # ADAPT: remove one '#' to use a line
##SBATCH --account=my_account
##SBATCH --gres=gpu:1                # a GPU node; then also export DEVICE=cuda below
set -euo pipefail

# module load python/3.12            # ADAPT: if your cluster provides Python through modules

export THREADS=${SLURM_CPUS_PER_TASK:-4}
export EVENTS=${EVENTS:-100000}      # events per shard
export OUT_DIR=${OUT_DIR:-data/shards}
# export DEVICE=cuda                 # on GPU nodes

bash examples/cluster/run_shard.sh "${SLURM_ARRAY_TASK_ID:?not running as a SLURM array task}"
